 void StartGameMonitor(){gameTimer=new System.Windows.Forms.Timer{Interval=1500};gameTimer.Tick+=(sender,e)=>PollGameRuns();gameTimer.Start();PollGameRuns();FormClosed+=(sender,e)=>gameTimer.Dispose();}
 void PollGameRuns(){if(monitorBusy||IsDisposed)return;monitorBusy=true;var worker=new BackgroundWorker();worker.DoWork+=(sender,e)=>e.Result=GameTools.Snapshot();worker.RunWorkerCompleted+=(sender,e)=>{monitorBusy=false;worker.Dispose();if(IsDisposed)return;if(e.Error!=null){if(monitorError!=e.Error.Message){monitorError=e.Error.Message;Log("Game state detection: "+monitorError);}return;}monitorError="";runtime.Observe((List<GameProcess>)e.Result);if(!busy){UpdateRunButton();foreach(ListViewItem row in list.Items){var game=(Game)row.Tag;var state=runtime.State(game.Root,DateTime.UtcNow);string prefix=state==GameRunState.Running?T("Running · ","运行中 · ","執行中 · "):state==GameRunState.Starting?T("Starting · ","启动中 · ","啟動中 · "):state==GameRunState.Stopping?T("Stopping · ","停止中 · ","停止中 · "):state==GameRunState.NotDetected?T("Launch not detected · ","未检测到启动 · ","未偵測到啟動 · "):"";string text=prefix+RowStatus(game);if(row.SubItems[1].Text!=text)row.SubItems[1].Text=text;}}};worker.RunWorkerAsync();}
 void UpdateRunButton(){var game=Selected();var state=game==null?GameRunState.Stopped:runtime.State(game.Root,DateTime.UtcNow);launch.Text=state==GameRunState.Running?T("Stop game","停止游戏","停止遊戲"):state==GameRunState.Starting?T("Starting…","启动中…","啟動中…"):state==GameRunState.Stopping?T("Stopping…","停止中…","停止中…"):state==GameRunState.Checking?T("Detecting status…","检测状态中…","偵測狀態中…"):T("Launch game","启动游戏","啟動遊戲");launch.Enabled=game!=null&&!busy&&state!=GameRunState.Starting&&state!=GameRunState.Stopping&&state!=GameRunState.Checking;if(game!=null&&(state==GameRunState.Running||state==GameRunState.Starting||state==GameRunState.Stopping)){repair.Enabled=restore.Enabled=false;help.Text=game.Name+" — "+T("Running / starting. Stop the game before patching or restoring.","运行或启动中，请停止游戏后再修补或还原。","執行或啟動中，請停止遊戲後再修補或還原。");}else if(game!=null&&!busy){repair.Enabled=true;restore.Enabled=AutoBridge.HasState(game.Root)||Profile(game)!=null||game.Status=="Patched";help.Text=game.Name+" — "+Mode(Profile(game))+"\n"+(state==GameRunState.NotDetected?T("No game process was detected within 45 seconds. Inspect logs or retry.","45 秒内未检测到游戏进程，请查看日志或重新尝试。","45 秒內未偵測到遊戲處理程序，請查看日誌或重新嘗試。"):T("Use Patch, Launch game or More for game actions.","使用“修补”“启动游戏”或“更多”进行操作。","使用「修補」「啟動遊戲」或「更多」進行操作。"));}}
 void ToggleGame(){if(busy||Selected()==null)return;var state=runtime.State(Selected().Root,DateTime.UtcNow);if(state==GameRunState.Running)StopGame();else if(state!=GameRunState.Starting&&state!=GameRunState.Stopping)Launch();}
 void StopGame(){var game=Selected();if(game==null)return;int sent=0;Run(()=>sent=GameTools.RequestClose(game.Root,GameTools.Processes(game.Root),Log),()=>{if(sent>0){runtime.Stopping(game.Root,DateTime.UtcNow);status.Text=T("Exit requested. Confirm any save prompts in the game. If it remains running, use More → Force close.","已请求正常退出，请在游戏中处理保存提示。若仍未退出，可通过“更多”强制关闭。","已要求正常結束，請在遊戲中處理儲存提示。若仍未結束，可透過「更多」強制關閉。");}else status.Text=T("No closable game window was found. Exit in the game or use More → Force close.","未找到可正常关闭的游戏窗口，请在游戏内退出，或通过“更多”强制关闭。","未找到可正常關閉的遊戲視窗，請在遊戲內結束，或透過「更多」強制關閉。");PollGameRuns();UpdateRunButton();});}
