 void OpenGameFolder(){var game=Selected();if(game==null)return;try{if(!Directory.Exists(game.Root))throw new Exception(T("Game folder no longer exists. Refresh the game list.","游戏目录已不存在，请刷新游戏列表。","遊戲目錄已不存在，請重新整理遊戲列表。"));System.Diagnostics.Process.Start(new System.Diagnostics.ProcessStartInfo(game.Root){UseShellExecute=true});}catch(Exception error){UiDialogs.Error(this,error.Message,Text,T("Close","关闭","關閉"));}}
 void ForceCloseGame(){var game=Selected();if(game==null)return;List<GameProcess> processes=null;Run(()=>processes=GameTools.Processes(game.Root),()=>{if(processes.Count==0){status.Text=T("No identifiable game-folder process was found.","未找到可识别的游戏进程。","未找到可識別的遊戲處理程序。");return;}if(!ConfirmGameAction(game,T("Force close game","强制关闭游戏","強制關閉遊戲"),T("Force closing may lose unsaved progress. The following game-folder processes will be terminated. Try exiting normally in the game first.","强制关闭可能丢失未保存的进度。将结束下列游戏目录内的进程，建议先尝试在游戏内正常退出。","強制關閉可能遺失未儲存的進度。將結束下列遊戲目錄內的處理程序，建議先嘗試在遊戲內正常結束。"),T("Force close","强制关闭","強制關閉"),processes)){status.Text=T("Force close cancelled.","已取消强制关闭。","已取消強制關閉。");return;}Run(()=>GameTools.ForceClose(game.Root,processes,Log),()=>status.Text=T("Game process close operation completed.","游戏进程关闭操作已完成。","遊戲處理程序關閉操作已完成。"));});}
 void UninstallGame(bool cleanup){var game=Selected();if(game==null)return;string description=cleanup?T("First restore the original files and clear this tool's patch backups, launch configuration and logs. Then open Steam's uninstall confirmation.\n\nCancelling in Steam will not undo that cleanup. Saves, mods and unrelated files are not cleared by Fixer.","先还原原版文件，清理本工具的修补备份、启动配置及日志，再打开 Steam 的卸载确认。\n\n即使随后在 Steam 取消卸载，修补清理也已执行。Fixer 不清理存档、模组及其他无关文件。","先還原原版檔案，清理本工具的修補備份、啟動設定及日誌，再開啟 Steam 的解除安裝確認。\n\n即使隨後在 Steam 取消解除安裝，修補清理也已執行。Fixer 不清理存檔、模組及其他無關檔案。") :T("Open Steam's uninstall confirmation. This option keeps Fixer launch profiles; Steam decides which game files to remove. Close the game first.","打开 Steam 的卸载确认。本选项保留 Fixer 启动配置；游戏文件由 Steam 处理。请先关闭游戏。","開啟 Steam 的解除安裝確認。本選項保留 Fixer 啟動設定；遊戲檔案由 Steam 處理。請先關閉遊戲。");if(!ConfirmGameAction(game,T("Uninstall game","卸载游戏","解除安裝遊戲"),description,cleanup?T("Clean and continue","清理并继续","清理並繼續"):T("Continue","继续","繼續")))return;Run(()=>{GameTools.UninstallArgument(game.AppId);if(!Core.IsSteamRoot(steam))throw new Exception("Steam installation unavailable");if(GameTools.Processes(game.Root).Count>0)throw new Exception(T("Close the game before uninstalling.","请先关闭游戏，再卸载。","請先關閉遊戲，再解除安裝。"));if(cleanup){GameTools.Cleanup(game,Log);profiles.Remove(game.Root);contexts.Remove(game.Root);Core.Inspect(game);}GameTools.Uninstall(steam,game);Log("Requested Steam uninstall: "+game.AppId+" | "+game.Name);},()=>{RefreshList(game.Root);status.Text=T("Confirm uninstall in Steam, then refresh the game list.","请在 Steam 中确认卸载，完成后刷新游戏列表。","請在 Steam 中確認解除安裝，完成後重新整理遊戲列表。");});}
 void UpdateSteamTools(){bool found=Core.IsSteamRoot(steam);steamPath.Text=found?steam:T("Steam folder not detected","未检测到 Steam 安装目录","未偵測到 Steam 安裝目錄");steamHint.ForeColor=found?UiTheme.Muted:UiTheme.Blue;steamHint.Text=found?T("Steam folder found. Use a compatible legacy client; Zstd verifies its exact client files.","已找到 Steam 目录。请使用兼容的旧版客户端；Zstd 会校验指定客户端文件。","已找到 Steam 目錄。請使用相容的舊版用戶端；Zstd 會校驗指定用戶端檔案。"):T("Already installed? Choose its folder or detect again. Otherwise download Steam, install a compatible legacy client, then detect again.","已安装？手动选择目录或重新检测。尚未安装？点击“下载 Steam”；安装兼容的旧版客户端后，再点击“重新检测 Steam”。","已安裝？手動選擇目錄或重新偵測。尚未安裝？點擊「下載 Steam」；安裝相容的舊版用戶端後，再點擊「重新偵測 Steam」。");((StyledButton)chooseSteam).Primary=!found;((StyledButton)downloadSteam).Primary=!found;chooseSteam.Invalidate();downloadSteam.Invalidate();}
 void ShowSteamGuide(){if(busy)return;games.Clear();profiles.Clear();contexts.Clear();UpdateSteamTools();RefreshList(null);status.Text=T("Steam was not detected. Use the Steam tools below to continue.","未检测到 Steam，请通过下方 Steam 工具继续设置。","未偵測到 Steam，請透過下方 Steam 工具繼續設定。");}
 void ChooseSteam(){if(busy)return;using(var folder=new FolderBrowserDialog{Description=T("Select the folder containing steam.exe","选择包含 steam.exe 的 Steam 安装目录","選擇包含 steam.exe 的 Steam 安裝目錄"),ShowNewFolderButton=false}){if(Core.IsSteamRoot(steam))folder.SelectedPath=steam;while(folder.ShowDialog(this)==DialogResult.OK){if(!Core.IsSteamRoot(folder.SelectedPath)){UiDialogs.Error(this,T("This folder does not contain steam.exe. Select the Steam installation folder, not steamapps or a game folder.","该目录中没有 steam.exe。请选择 Steam 安装目录，而不是 steamapps 或游戏目录。","此目錄中沒有 steam.exe。請選擇 Steam 安裝目錄，而不是 steamapps 或遊戲目錄。"),Text,T("Choose again","重新选择","重新選擇"));continue;}steam=Path.GetFullPath(folder.SelectedPath);games.Clear();profiles.Clear();contexts.Clear();UpdateSteamTools();RefreshList(null);Log("Steam folder selected: "+steam);Scan();return;}}}
 void DetectSteam(){if(busy)return;string detected=null;Run(()=>detected=Core.SteamRoot(),()=>{if(string.IsNullOrEmpty(detected)){if(Core.IsSteamRoot(steam)){UpdateSteamTools();status.Text=T("Automatic detection found no registered/default installation; the selected folder is retained.","自动检测未找到安装目录，已保留当前手动选择的有效目录。","自動偵測未找到安裝目錄，已保留目前手動選擇的有效目錄。");}else{steam="";ShowSteamGuide();}return;}steam=detected;games.Clear();profiles.Clear();contexts.Clear();UpdateSteamTools();RefreshList(null);Log("Steam detected: "+steam);Scan();});}
 void FitColumns(){if(list.Columns.Count!=5)return;int width=Math.Max(1,list.ClientSize.Width-2-SystemInformation.VerticalScrollBarWidth);double[] weights={.25,.22,.18,.10,.25};int used=0;for(int i=0;i<4;i++){int size=(int)(width*weights[i]);list.Columns[i].Width=size;used+=size;}list.Columns[4].Width=Math.Max(1,width-used);}
 void Setup(Button b,string text,Action action){b.Text=text;b.Dock=DockStyle.Fill;b.Height=38;b.Font=new Font(Font.FontFamily,9,FontStyle.Regular);b.Margin=new Padding(3,4,6,4);b.Click+=(s,e)=>action();}
 Game Selected(){return list.SelectedItems.Count==0?null:(Game)list.SelectedItems[0].Tag;}
 LaunchProfile Profile(Game g){LaunchProfile p;return g!=null&&profiles.TryGetValue(g.Root,out p)?p:null;}
 void ReadProfiles(){profiles.Clear();if(!Directory.Exists(LaunchProfiles.Folder))return;var files=new List<string>(Directory.GetFiles(LaunchProfiles.Folder,"*.json"));files.Sort((a,b)=>File.GetLastWriteTimeUtc(a).CompareTo(File.GetLastWriteTimeUtc(b)));foreach(string path in files)try{var p=LaunchProfiles.Load(Path.GetFileNameWithoutExtension(path));profiles[p.Root]=p;}catch(Exception e){Log("Saved profile: "+e.Message);}}
 string RowStatus(Game g){if(AutoBridge.HasState(g.Root))return T("Replacement bridge installed","已安装替换桥接","已安裝替換橋接");var p=Profile(g);if(p!=null)return p.Mode=="inject"?T("Injection configured","已配置注入启动","已設定注入啟動"):T("Repair configured","已配置修补","已設定修補");if(g.Status=="Patched")return T("Dedicated repair installed","已安装专用修补","已安裝專用修補");if(g.Status=="Mismatch")return T("Version / backup needs checking","版本或备份待检查","版本或備份待檢查");return T("Not checked","尚未检查","尚未檢查");}
 string Mode(LaunchProfile p){if(p==null)return T("Normal Steam launch","普通 Steam 启动","一般 Steam 啟動");return p.Mode=="inject"?T("Memory injection","内存注入","記憶體注入"):p.Mode=="module"?T("Dedicated repair","专用修补","專用修補"):T("DLL replacement","DLL 替换桥接","DLL 替換橋接");}
 void RefreshList(string preferred){if(busy)return;Game old=Selected();string selected=preferred??(old==null?null:old.Root);list.BeginUpdate();list.Items.Clear();foreach(var g in games){string q=filter.Text.Trim();if(q!=""&&g.Name.IndexOf(q,StringComparison.OrdinalIgnoreCase)<0&&g.AppId.IndexOf(q,StringComparison.OrdinalIgnoreCase)<0)continue;var row=new ListViewItem(new[]{g.Name,RowStatus(g),Mode(Profile(g)),g.AppId,g.Root});row.Tag=g;row.ToolTipText=g.Name+"\n"+g.Root;list.Items.Add(row);if(selected!=null&&g.Root.Equals(selected,StringComparison.OrdinalIgnoreCase)){row.Selected=true;row.Focused=true;}}list.EndUpdate();UpdateState();}
 void UpdateState(){Game g=Selected();bool selected=g!=null&&!busy;scan.Enabled=filter.Enabled=!busy;manage.Enabled=true;if(diagnosticRefresh!=null)diagnosticRefresh.Enabled=!busy;list.Enabled=!busy;repair.Enabled=launch.Enabled=more.Enabled=selected;restore.Enabled=selected&&(AutoBridge.HasState(g.Root)||Profile(g)!=null||g.Status=="Patched");zstd.Enabled=!busy&&Core.IsSteamRoot(steam);
 repair.Text=g!=null&&AutoBridge.HasState(g.Root)?T("Restore and repatch","还原并修补","還原並修補"):T("Patch","修补","修補");
 help.Text=!Core.IsSteamRoot(steam)?T("Steam was not found. Install it or select its folder in Steam tools below.","未检测到 Steam，请先在下方安装 Steam 或手动选择目录。","未偵測到 Steam，請先在下方安裝 Steam 或手動選擇目錄。"):g==null?T("Select a game above, then Patch or Launch game. Steam tools are in the separate area below.","在上方选择游戏，再点击“修补”或“启动游戏”。Steam 相关操作位于下方独立区域。","在上方選擇遊戲，再點擊「修補」或「啟動遊戲」。Steam 相關操作位於下方獨立區域。"):g.Name+" — "+Mode(Profile(g))+"\n"+T("Patch automatically checks interfaces, then lets you choose a method. Saved injection configuration is used when launching.","“修补”会自动检查接口，然后让你选择方式；已保存的注入配置会在启动时使用。","「修補」會自動檢查介面，然後讓你選擇方式；已儲存的注入設定會在啟動時使用。");UpdateRunButton();}
 void Scan(){if(!Core.IsSteamRoot(steam)){ShowSteamGuide();return;}string keep=Selected()==null?null:Selected().Root;Run(()=>{if(string.IsNullOrEmpty(steam)||!Directory.Exists(steam))throw new Exception(T("Set a valid Steam folder in Diagnostics / logs.","请在下方“Steam 工具”中选择有效的 Steam 目录。","請在「診斷 / 日誌」中選擇有效的 Steam 目錄。"));games=Core.Scan(steam,Log);games.Sort((a,b)=>StringComparer.CurrentCultureIgnoreCase.Compare(a.Name,b.Name));ReadProfiles();},()=>{RefreshList(keep);status.Text=T("Installed games: ","已安装游戏：","已安裝遊戲：")+games.Count;});}
 string ChooseExe(Game g){var saved=Profile(g);if(saved!=null&&File.Exists(Core.Inside(g.Root,saved.Exe)))return saved.Exe;string exact=Path.Combine(g.Root,Path.GetFileName(g.Root)+".exe");if(File.Exists(exact))return Path.GetFileName(exact);if(g.Module!=null&&g.Module.Marker.EndsWith(".exe",StringComparison.OrdinalIgnoreCase)&&File.Exists(Core.Inside(g.Root,g.Module.Marker)))return g.Module.Marker;
 var choices=new List<string>();foreach(string p in Directory.GetFiles(g.Root,"*.exe")){string name=Path.GetFileName(p).ToLowerInvariant();if(!name.Contains("crash")&&!name.Contains("unins")&&!name.StartsWith("legacy")&&!name.StartsWith("unity"))choices.Add(p);}if(choices.Count==1)return Path.GetFileName(choices[0]);
 using(var d=new OpenFileDialog{Filter=T("Game executable (*.exe)|*.exe","游戏程序 (*.exe)|*.exe","遊戲程式 (*.exe)|*.exe"),InitialDirectory=g.Root,Title=T("Select this game's main executable","选择该游戏的主程序","選擇該遊戲的主程式")}){if(d.ShowDialog(this)!=DialogResult.OK)return null;string prefix=Path.GetFullPath(g.Root).TrimEnd('\\','/')+Path.DirectorySeparatorChar;if(!d.FileName.StartsWith(prefix,StringComparison.OrdinalIgnoreCase))throw new Exception(T("Choose an executable inside the selected game folder.","请选择所选游戏目录内的程序。","請選擇所選遊戲目錄內的程式。"));return d.FileName.Substring(prefix.Length);}}
 void RepairDedicated(Game g){Run(()=>{LaunchProfiles.CheckIdle(g);if(AutoBridge.HasState(g.Root)||Profile(g)!=null)throw new Exception(T("Restore the existing patch / launch configuration before dedicated repair.","请先点击“还原”移除已有修补 / 启动配置，再进行专用修补。","請先點擊「還原」移除既有修補 / 啟動設定，再進行專用修補。"));Core.Inspect(g);if(g.Module==null)throw new Exception(T("The dedicated tModLoader module could not match this installation. Verify game files in Steam; do not select another executable.","未匹配到 tModLoader 专用模块。请先在 Steam 验证游戏文件完整性，无需选择其他 EXE。","未匹配到 tModLoader 專用模組。請先在 Steam 驗證遊戲檔案完整性，無須選擇其他 EXE。"));if(g.Status=="Patched"){Log("Dedicated repair already applied: "+g.Name);return;}if(g.Status!="Ready")throw new Exception(T("This tModLoader version / backup is not supported by the dedicated patch. No files were changed.\n","当前 tModLoader 版本或备份未通过专用修补校验，未修改文件。\n","目前 tModLoader 版本或備份未通過專用修補校驗，未修改檔案。\n")+g.Status+"\n"+g.Detail);Core.Apply(g,false,Log);contexts.Remove(g.Root);},()=>{RefreshList(g.Root);status.Text=T("Dedicated patch files verified. Click Launch game to test through Steam.","专用修补文件已校验，点击“启动游戏”通过 Steam 测试。","專用修補檔案已校驗，點擊「啟動遊戲」透過 Steam 測試。");});}
 void Repair(){Game g=Selected();if(g==null)return;if(Core.RequiresDedicatedRepair(g)){RepairDedicated(g);return;}string exe;try{exe=ChooseExe(g);}catch(Exception e){UiDialogs.Error(this,e.Message,Text,T("Close","关闭","關閉"));return;}if(exe==null)return;var ctx=new RepairContext{Game=g,Exe=exe,Api="",Error=""};
 Run(()=>{LaunchProfiles.CheckIdle(g);if(AutoBridge.HasState(g.Root)){AutoBridge.Restore(g.Root,Log);var old=Profile(g);if(old!=null){LaunchProfiles.Remove(old);profiles.Remove(g.Root);}}
 Core.Inspect(g);if(g.Status=="Patched")throw new Exception(T("Restore the previous dedicated patch before switching to the generic method.","请先点击“还原”撤销旧专用修补，再切换通用方式。","請先點擊「還原」撤銷舊專用修補，再切換通用方式。"));ctx.Report=Analyzer.Analyze(g,steam,Log);try{ctx.Plan=AutoBridge.Plan(g,ctx.Report);ctx.Api=LaunchProfiles.ValidateInjectionPlan(g,exe,ctx.Plan);}catch(Exception e){ctx.Error=e.Message;Log("Plan: "+e.Message);}contexts[g.Root]=ctx;
 if(ctx.Plan==null)throw new Exception(T("No supported patch plan. Details are available in Diagnostics / logs.","没有找到受支持的修补方案，可在“诊断 / 日志”中查看详情。","沒有找到受支援的修補方案，可在「診斷 / 日誌」中查看詳情。")+"\n"+ctx.Error);
 },()=>{RefreshList(g.Root);ChooseMethod(ctx);});}
 void ChooseMethod(RepairContext ctx){using(var d=new ThemedForm{Text=T("Patch selected game","修补所选游戏","修補所選遊戲"),ClientSize=new Size(700,340),StartPosition=FormStartPosition.CenterParent,FormBorderStyle=FormBorderStyle.FixedDialog,MaximizeBox=false,MinimizeBox=false,Font=Font,BackColor=UiTheme.Background,ForeColor=UiTheme.Text}){
 var l=UiDialogs.Layout(4);l.RowStyles.Add(new RowStyle(SizeType.Absolute,76));l.RowStyles.Add(new RowStyle(SizeType.Absolute,84));l.RowStyles.Add(new RowStyle(SizeType.Absolute,84));l.RowStyles.Add(new RowStyle(SizeType.Percent,100));d.Controls.Add(l);
 l.Controls.Add(new Label{Dock=DockStyle.Fill,Text=ctx.Game.Name+"\n"+T("Choose a method, then save the patch. Then click Launch game in the main window.","第 1 步：选择方式并保存。第 2 步：回主界面点击“启动游戏”。","選擇修補方式並儲存，隨後在主介面點擊「啟動遊戲」。")},0,0);
 var inj=new RadioButton{Dock=DockStyle.Fill,Padding=new Padding(8),Margin=new Padding(0,4,0,4),BackColor=Color.White,Enabled=ctx.Api!="",Text=T("Injection launch (keep original files)\nSave configuration, then launch through this tool.","注入启动（保留原文件）\n保存启动配置后，需要从本工具启动游戏。","注入啟動（保留原檔案）\n儲存啟動設定後，須從本工具啟動遊戲。")};var rep=new RadioButton{Dock=DockStyle.Fill,Padding=new Padding(8),Margin=new Padding(0,4,0,4),BackColor=Color.White,Enabled=ctx.Plan!=null,Text=T("DLL replacement: install with backup and restore support","DLL 替换桥接\n先备份再替换；检查文件的游戏可能拒绝启动。","DLL 替換橋接：備份後安裝，支援還原")};
 bool preferred=inj.Enabled&&ctx.Game.Name.IndexOf("Dancing Line",StringComparison.OrdinalIgnoreCase)>=0;inj.Checked=preferred||!rep.Enabled;rep.Checked=!inj.Checked;l.Controls.Add(inj,0,1);l.Controls.Add(rep,0,2);Button ok,cancel;var bar=UiDialogs.Buttons(T("Cancel","取消","取消"),T("Save patch","保存修补","儲存修補"),out ok,out cancel);l.Controls.Add(bar,0,3);d.AcceptButton=ok;d.CancelButton=cancel;if(d.ShowDialog(this)!=DialogResult.OK){status.Text=T("Patch selection cancelled.","已取消修补方式选择。","已取消修補方式選擇。");return;}bool useInject=inj.Checked;
 Run(()=>{LaunchProfiles.CheckIdle(ctx.Game);var p=new LaunchProfile{Name=ctx.Game.Name,Root=ctx.Game.Root,Exe=ctx.Exe,Steam=steam,AppId=ctx.Game.AppId};if(useInject){if(ctx.Plan==null||ctx.Api=="")throw new Exception("Injection plan unavailable");p.Mode="inject";p.Api=ctx.Api;p.ApiHash=LaunchProfiles.SelectInjectionFile(ctx.Exe,ctx.Plan).OriginalHash;p.ClientHash=ctx.Plan.ClientHash;if(Core.Hash(Core.Inside(p.Root,p.Api))!=p.ApiHash)throw new Exception("Game changed after analysis");}
 else{AutoBridge.Install(ctx.Plan,Log);p.Mode="generic";}LaunchProfiles.Save(p);profiles[p.Root]=p;Core.Inspect(ctx.Game);},()=>{RefreshList(ctx.Game.Root);status.Text=T("Patch/configuration saved. Click Launch game to test.","修补 / 注入配置已保存，点击“启动游戏”测试。","修補 / 注入設定已儲存，點擊「啟動遊戲」測試。");});}}
 void SteamLaunchFallback(LaunchProfile p,string error){using(var d=new ThemedForm{Text=T("Steam launch modes unavailable","Steam 启动模式不可用","Steam 啟動模式不可用"),ClientSize=new Size(700,330),Font=Font,StartPosition=FormStartPosition.CenterParent,FormBorderStyle=FormBorderStyle.FixedDialog,MinimizeBox=false,MaximizeBox=false}){var l=UiDialogs.Layout(2);l.RowStyles.Add(new RowStyle(SizeType.Percent,100));l.RowStyles.Add(new RowStyle(SizeType.Absolute,52));l.Controls.Add(new TextBox{Dock=DockStyle.Fill,Multiline=true,ReadOnly=true,ScrollBars=ScrollBars.Vertical,Text=T("Open the game page in Steam and retry. You can also launch normally through Steam; injection will not be applied.\n\n","请在 Steam 打开该游戏页面后重试。也可选择普通 Steam 启动，本次不会注入。\n\n","請在 Steam 開啟該遊戲頁面後重試。亦可選擇一般 Steam 啟動，本次不會注入。\n\n")+error},0,0);Button ok,cancel;l.Controls.Add(UiDialogs.Buttons(T("Cancel","取消","取消"),T("Steam launch","Steam 启动","Steam 啟動"),out ok,out cancel),0,1);d.Controls.Add(l);d.AcceptButton=ok;d.CancelButton=cancel;if(d.ShowDialog(this)==DialogResult.OK){Run(()=>System.Diagnostics.Process.Start(new System.Diagnostics.ProcessStartInfo(Core.Inside(p.Steam,"steam.exe"),"-applaunch "+p.AppId){UseShellExecute=false}),()=>status.Text=T("Normal Steam launch requested.","已请求普通 Steam 启动。","已請求一般 Steam 啟動。"));}else status.Text=T("Launch cancelled.","已取消启动。","已取消啟動。");}}
 LaunchProfile SelectInjectionMode(LaunchProfile saved,Game game){List<SteamLaunchMode> modes;string custom;try{modes=SteamLaunchModes.ReadModes(saved.Steam,saved.Root,uint.Parse(saved.AppId));custom=LaunchOptions.SteamArguments(saved.Steam,saved.AppId)??"";}catch(Exception e){SteamLaunchFallback(saved,e.Message);return null;}SteamLaunchMode mode=modes[0];if(modes.Count>1){using(var d=new ThemedForm{Text=T("Choose launch mode","选择启动模式","選擇啟動模式"),ClientSize=new Size(700,300),Font=Font,StartPosition=FormStartPosition.CenterParent,FormBorderStyle=FormBorderStyle.FixedDialog,MinimizeBox=false,MaximizeBox=false}){var l=UiDialogs.Layout(4);l.RowStyles.Add(new RowStyle(SizeType.Absolute,54));l.RowStyles.Add(new RowStyle(SizeType.Absolute,44));l.RowStyles.Add(new RowStyle(SizeType.Percent,100));l.RowStyles.Add(new RowStyle(SizeType.Absolute,52));l.Controls.Add(new Label{Text=game.Name+"\n"+T("Launch modes read automatically from Steam.","已自动读取 Steam 启动模式，无需填写参数。","已自動讀取 Steam 啟動模式，無須填寫參數。"),Dock=DockStyle.Fill},0,0);var select=new ComboBox{Dock=DockStyle.Fill,DropDownStyle=ComboBoxStyle.DropDownList};foreach(var m in modes)select.Items.Add(m);select.SelectedIndex=0;var detail=new Label{Dock=DockStyle.Fill,ForeColor=UiTheme.Muted};Action show=()=>{var m=(SteamLaunchMode)select.SelectedItem;detail.Text=m.Executable+"\n"+m.Arguments+"\n"+T("Steam custom arguments: ","Steam 自定义参数：","Steam 自訂參數：")+custom;};select.SelectedIndexChanged+=(s,e)=>show();show();l.Controls.Add(select,0,1);l.Controls.Add(detail,0,2);Button ok,cancel;l.Controls.Add(UiDialogs.Buttons(T("Cancel","取消","取消"),T("Launch game","启动游戏","啟動遊戲"),out ok,out cancel),0,3);d.Controls.Add(l);d.AcceptButton=ok;d.CancelButton=cancel;if(d.ShowDialog(this)!=DialogResult.OK){status.Text=T("Launch cancelled.","已取消启动。","已取消啟動。");return null;}mode=(SteamLaunchMode)select.SelectedItem;}}try{var p=new LaunchProfile{Id=saved.Id,Name=saved.Name,Root=saved.Root,Steam=saved.Steam,AppId=saved.AppId,Mode=saved.Mode,Exe=mode.Executable,Api=saved.Api,ApiHash=saved.ApiHash,ClientHash=saved.ClientHash,Overlay=saved.Overlay,WorkingDirectory=mode.WorkingDirectory,Arguments=(mode.Arguments+" "+custom).Trim()};LaunchOptions.Validate(p.Arguments);if(!p.Exe.Equals(saved.Exe,StringComparison.OrdinalIgnoreCase)){var report=Analyzer.Analyze(game,p.Steam,Log);var plan=AutoBridge.Plan(game,report);p.Api=LaunchProfiles.ValidateInjectionPlan(game,p.Exe,plan);p.ApiHash=LaunchProfiles.SelectInjectionFile(p.Exe,plan).OriginalHash;p.ClientHash=plan.ClientHash;}else LaunchProfiles.ValidateInjectionPlan(game,p.Exe,new AutoPlan{Files=new List<AutoFile>{new AutoFile{Path=p.Api,OriginalHash=p.ApiHash}}});Log("Steam launch mode: "+mode.Id+" | "+mode.Name+" | "+mode.Executable);return p;}catch(Exception e){UiDialogs.Error(this,e.Message,Text,T("Close","关闭","關閉"));status.Text=T("Selected mode is not supported by injection.","所选模式暂不支持注入启动。","所選模式暫不支援注入啟動。");return null;}}
 void Launch(){Game g=Selected();if(g==null)return;var state=runtime.State(g.Root,DateTime.UtcNow);if(state==GameRunState.Running||state==GameRunState.Stopping||state==GameRunState.Starting)return;var p=Profile(g);if(p!=null&&p.Mode=="inject"){p=SelectInjectionMode(p,g);if(p==null)return;}runtime.Launch(g.Root,DateTime.UtcNow);Run(()=>{if(p!=null)LaunchProfiles.Launch(p,Log);else{uint id;if(!uint.TryParse(g.AppId,out id)||id==0)throw new Exception("Installed AppID unavailable");System.Diagnostics.Process.Start(new System.Diagnostics.ProcessStartInfo(Core.Inside(steam,"steam.exe"),"-applaunch "+g.AppId){UseShellExecute=false});Log("Normal Steam launch requested; no saved injection configuration was used.");}},()=>{PollGameRuns();UpdateRunButton();status.Text=T("Launch requested; waiting for the game process…","已发起启动，正在等待游戏进程…","已發起啟動，正在等待遊戲處理程序…");},()=>{runtime.CancelLaunch(g.Root);UpdateRunButton();});}
 void Restore(){Game g=Selected();if(g==null)return;Run(()=>{LaunchProfiles.CheckIdle(g);if(AutoBridge.HasState(g.Root))AutoBridge.Restore(g.Root,Log);else{Core.Inspect(g);if(g.Module!=null&&g.Status=="Patched")Core.Apply(g,true,Log);}if(Directory.Exists(LaunchProfiles.Folder))foreach(string file in Directory.GetFiles(LaunchProfiles.Folder,"*.json")){LaunchProfile saved;try{saved=LaunchProfiles.Load(Path.GetFileNameWithoutExtension(file));}catch(Exception e){Log("Saved profile retained: "+e.Message);continue;}if(saved.Root.Equals(g.Root,StringComparison.OrdinalIgnoreCase))LaunchProfiles.Remove(saved);}profiles.Remove(g.Root);Core.Inspect(g);contexts.Remove(g.Root);},()=>{RefreshList(g.Root);status.Text=T("Patch restored / launch setup removed; original files retained.","已还原修补 / 移除启动配置，保留原文件。","已還原修補 / 移除啟動設定，保留原檔案。");});}
 void EnableZstd(){using(var d=new ThemedForm{Text=T("Zstd download support","Zstd 下载补丁","Zstd 下載補丁"),ClientSize=new Size(660,300),StartPosition=FormStartPosition.CenterParent,FormBorderStyle=FormBorderStyle.FixedDialog,MaximizeBox=false,MinimizeBox=false,Font=Font,BackColor=UiTheme.Background,ForeColor=UiTheme.Text}){var l=UiDialogs.Layout(2);l.RowStyles.Add(new RowStyle(SizeType.Percent,100));l.RowStyles.Add(new RowStyle(SizeType.Absolute,52));l.Controls.Add(new Label{Dock=DockStyle.Fill,Margin=new Padding(0),Text=T("Enable Zstd decompression for the supported Steam client.\n\n1. Pause downloads and close games.\n2. Click Enable and accept the Windows administrator prompt.\n3. Resume downloads after Fixer reports success.\n\nSteam starts automatically if needed. Reapply after Steam exits or restarts.","为受支持的 Steam 客户端添加 Zstd 解压支持。\n\n1. 暂停下载并关闭游戏。\n2. 点击“启用补丁”，允许 Windows 管理员权限请求。\n3. 补丁报告成功后，继续下载。\n\nSteam 未运行时会自动启动；完全退出或重启后需再次启用。","為受支援的 Steam 用戶端加入 Zstd 解壓支援。\n\n1. 暫停下載並關閉遊戲。\n2. 點擊「啟用補丁」，允許 Windows 管理員權限請求。\n3. 補丁回報成功後，繼續下載。\n\nSteam 未執行時會自動啟動；完全退出或重新啟動後須再次啟用。")},0,0);Button ok,cancel;l.Controls.Add(UiDialogs.Buttons(T("Cancel","取消","取消"),T("Enable patch","启用补丁","啟用補丁"),out ok,out cancel),0,1);d.Controls.Add(l);d.AcceptButton=ok;d.CancelButton=cancel;if(d.ShowDialog(this)!=DialogResult.OK)return;}ZstdOutcome outcome=ZstdOutcome.Applied;Run(()=>outcome=ZstdSupport.Enable(steam,Log),()=>{if(outcome==ZstdOutcome.AlreadyEnabled){status.Text=T("Zstd is already enabled; no repeat patch was applied.","Zstd 补丁已启用，无需重复应用。","Zstd 補丁已啟用，無須重複套用。");UiDialogs.Notice(this,status.Text+"\n\n"+T("Reapply only after Steam fully exits or restarts.","仅在 Steam 完全退出或重启后，才需要重新启用。","僅在 Steam 完全結束或重新啟動後，才需要重新啟用。"),T("Patch already enabled","补丁已启用","補丁已啟用"),T("OK","知道了","知道了"));}else status.Text=T("Zstd enabled successfully. Reapply after Steam restarts.","Zstd 补丁已成功启用；Steam 重启后需再次启用。","Zstd 補丁已成功啟用；Steam 重新啟動後需再次啟用。");});}
 void SaveUpdateSettings(){try{updateSettings.Save();}catch(Exception e){Log("Update settings could not be saved: "+e.Message);}}
 void UpdateBadge(){if(updates==null)return;updates.Text=updateChecking?T("Checking…","正在检查…","正在檢查…"):availableUpdate!=null?T("Update available","有更新","有更新"):T("Updates","检查更新","檢查更新");updates.Primary=availableUpdate!=null;updateTip.SetToolTip(updates,availableUpdate==null?T("Check for software updates","检查软件更新","檢查軟體更新"):T("New version: ","新版本：","新版本：")+availableUpdate.tag_name);updates.Invalidate();}
