 void Updates(){using(var d=new ThemedForm{Text=T("Updates","软件更新","軟體更新"),ClientSize=new Size(640,290),Font=Font,StartPosition=FormStartPosition.CenterParent,MinimizeBox=false,MaximizeBox=false,FormBorderStyle=FormBorderStyle.FixedDialog}){var l=UiDialogs.Layout(4);l.RowStyles.Add(new RowStyle(SizeType.Absolute,76));l.RowStyles.Add(new RowStyle(SizeType.Absolute,44));l.RowStyles.Add(new RowStyle(SizeType.Percent,100));l.RowStyles.Add(new RowStyle(SizeType.Absolute,52));l.Controls.Add(new Label{Dock=DockStyle.Fill,Text=T("Current version: ","当前版本：","目前版本：")+AppInfo.Version+(availableUpdate==null?"":"\n"+T("Available version: ","可更新版本：","可更新版本：")+availableUpdate.tag_name)+"\n"+T("Updates are downloaded and verified before you choose to restart.","先下载并校验更新，再由你选择重启安装。","先下載並校驗更新，再由你選擇重新啟動安裝。")},0,0);var automatic=new CheckBox{Dock=DockStyle.Fill,Checked=updateSettings.Automatic,Text=T("Automatically check at startup (at most once per day)","启动时自动检查更新（每天最多一次）","啟動時自動檢查更新（每天最多一次）")};var channel=new CheckBox{Dock=DockStyle.Fill,Checked=updateSettings.Preview,Text=T("Include test releases","包含测试版更新","包含測試版更新")};l.Controls.Add(automatic,0,1);l.Controls.Add(channel,0,2);Button ok,cancel;l.Controls.Add(UiDialogs.Buttons(T("Cancel","取消","取消"),(availableUpdate==null?T("Save and check","保存并检查","儲存並檢查"):T("View update","查看更新","查看更新")),out ok,out cancel),0,3);d.Controls.Add(l);d.AcceptButton=ok;d.CancelButton=cancel;if(d.ShowDialog(this)!=DialogResult.OK)return;updateSettings.Automatic=automatic.Checked;if(updateSettings.Preview!=channel.Checked){availableUpdate=null;UpdateBadge();}updateSettings.Preview=channel.Checked;SaveUpdateSettings();}if(availableUpdate!=null)PresentUpdate(availableUpdate);else CheckUpdates(false);}
 void CheckUpdates(bool automatic){if(updateChecking)return;updateChecking=true;updates.Enabled=false;UpdateBadge();bool preview=updateSettings.Preview;updateSettings.LastAttemptUtc=DateTime.UtcNow;SaveUpdateSettings();if(!automatic)status.Text=T("Checking for updates…","正在检查更新…","正在檢查更新…");var worker=new BackgroundWorker();worker.DoWork+=(s,e)=>e.Result=UpdateService.Check(preview);worker.RunWorkerCompleted+=(s,e)=>{updateChecking=false;worker.Dispose();if(IsDisposed)return;updates.Enabled=!busy;UpdateBadge();if(e.Error!=null){Log("Update check: "+e.Error.Message);if(!automatic){status.Text=T("Could not check for updates.","无法检查更新。","無法檢查更新。");UiDialogs.Error(this,e.Error.Message,Text,T("Close","关闭","關閉"));}return;}availableUpdate=(UpdateRelease)e.Result;UpdateBadge();if(availableUpdate==null){if(!automatic&&!busy)status.Text=T("No newer release is published for this channel.","当前通道暂无已发布的更新版本。","目前通道暫無已發佈的更新版本。");return;}Log("Update available: "+availableUpdate.tag_name);if(!automatic&&!busy)status.Text=T("An update is available. Click the update button to view it.","发现新版本，点击右上方“有更新”查看。","發現新版本，點擊右上方「有更新」查看。");};worker.RunWorkerAsync();}
 void PresentUpdate(UpdateRelease release){using(var d=new ThemedForm{Text=T("Update available: ","发现更新：","發現更新：")+release.tag_name,ClientSize=new Size(700,430),Font=Font,StartPosition=FormStartPosition.CenterParent,MinimizeBox=false,MaximizeBox=false,FormBorderStyle=FormBorderStyle.FixedDialog}){var l=UiDialogs.Layout(2);l.RowStyles.Add(new RowStyle(SizeType.Percent,100));l.RowStyles.Add(new RowStyle(SizeType.Absolute,52));l.Controls.Add(new TextBox{Multiline=true,ReadOnly=true,ScrollBars=ScrollBars.Vertical,Dock=DockStyle.Fill,Text=release.body??release.tag_name,BackColor=Color.White},0,0);Button ok,cancel;l.Controls.Add(UiDialogs.Buttons(T("Later","稍后","稍後"),T("Download update","下载更新","下載更新"),out ok,out cancel),0,1);d.Controls.Add(l);d.AcceptButton=ok;d.CancelButton=cancel;if(d.ShowDialog(this)!=DialogResult.OK)return;}DownloadUpdate(release);}
 void DownloadUpdate(UpdateRelease release){UpdateTicket staged=null;string workspace=null;Exception failure=null;bool finished=false;using(var cancel=new System.Threading.CancellationTokenSource())using(var d=new ThemedForm{Text=T("Downloading update","下载更新","下載更新"),ClientSize=new Size(620,230),Font=Font,StartPosition=FormStartPosition.CenterParent,MinimizeBox=false,MaximizeBox=false,FormBorderStyle=FormBorderStyle.FixedDialog}){
 var l=UiDialogs.Layout(3);l.RowStyles.Add(new RowStyle(SizeType.Percent,100));l.RowStyles.Add(new RowStyle(SizeType.Absolute,30));l.RowStyles.Add(new RowStyle(SizeType.Absolute,52));var detail=new Label{Dock=DockStyle.Fill,Text=T("Downloading and verifying the runtime package…","正在下载并校验完整运行包…","正在下載並校驗完整執行包…")};var progress=new ProgressBar{Dock=DockStyle.Fill,Style=ProgressBarStyle.Marquee};var stop=new StyledButton{Dock=DockStyle.Right,Width=150,Text=T("Cancel","取消","取消")};Action stopDownload=()=>{cancel.Cancel();stop.Enabled=false;detail.Text=T("Cancelling…","正在取消…","正在取消…");};stop.Click+=(s,e)=>stopDownload();l.Controls.Add(detail,0,0);l.Controls.Add(progress,0,1);l.Controls.Add(stop,0,2);d.Controls.Add(l);d.FormClosing+=(s,e)=>{if(!finished){e.Cancel=true;stopDownload();}};
 var worker=new BackgroundWorker{WorkerReportsProgress=true};worker.DoWork+=(s,e)=>{workspace=SelfUpdate.NewWorkspace();string package=Path.Combine(workspace,UpdateService.Package(release).name);UpdateService.Download(release,package,(received,total)=>worker.ReportProgress(total>0?(int)Math.Min(100,received*100/total):0,new long[]{received,total}),cancel.Token);cancel.Token.ThrowIfCancellationRequested();staged=SelfUpdate.Stage(package,workspace,Core.Base,release.tag_name);cancel.Token.ThrowIfCancellationRequested();};worker.ProgressChanged+=(s,e)=>{if(cancel.IsCancellationRequested)return;var bytes=(long[])e.UserState;if(bytes[1]>0){progress.Style=ProgressBarStyle.Continuous;progress.Value=e.ProgressPercentage;}detail.Text=T("Downloading update: ","正在下载更新：","正在下載更新：")+(bytes[1]>0?e.ProgressPercentage+"%":bytes[0]/1024+" KB");};worker.RunWorkerCompleted+=(s,e)=>{failure=e.Error;finished=true;d.Close();};d.Shown+=(s,e)=>worker.RunWorkerAsync();busy=true;UpdateState();try{d.ShowDialog(this);}finally{busy=false;UpdateState();worker.Dispose();}
 if(cancel.IsCancellationRequested||failure!=null){if(workspace!=null)try{Directory.Delete(workspace,true);}catch{}status.Text=cancel.IsCancellationRequested?T("Update cancelled.","已取消更新。","已取消更新。"):T("Update preparation failed; current version retained.","更新准备失败，保留当前版本。","更新準備失敗，保留目前版本。");if(!cancel.IsCancellationRequested)UiDialogs.Error(this,failure.Message,Text,T("Close","关闭","關閉"));return;}}
 using(var d=new ThemedForm{Text=T("Update ready","更新已就绪","更新已就緒"),ClientSize=new Size(650,250),Font=Font,StartPosition=FormStartPosition.CenterParent,MinimizeBox=false,MaximizeBox=false,FormBorderStyle=FormBorderStyle.FixedDialog}){var l=UiDialogs.Layout(2);l.RowStyles.Add(new RowStyle(SizeType.Percent,100));l.RowStyles.Add(new RowStyle(SizeType.Absolute,52));l.Controls.Add(new Label{Dock=DockStyle.Fill,Text=T("Download and SHA256 verification complete. Restart to install the update.\n\nProfiles, settings and logs will be retained. Close other Fixer windows first. If Zstd is enabled, exit Steam to release its module.","下载与 SHA256 校验完成，重启后安装更新。\n\n保留游戏配置、设置和日志；请先关闭其他 Fixer 窗口；启用过 Zstd 时，也请退出 Steam 以解除模块占用。","下載與 SHA256 校驗完成，重新啟動後安裝更新。\n\n保留遊戲設定、設定和日誌；請先關閉其他 Fixer 視窗；啟用過 Zstd 時，也請結束 Steam 以解除模組佔用。")},0,0);Button ok,back;l.Controls.Add(UiDialogs.Buttons(T("Later","稍后","稍後"),T("Restart and update","重启并更新","重新啟動並更新"),out ok,out back),0,1);d.Controls.Add(l);d.AcceptButton=ok;d.CancelButton=back;if(d.ShowDialog(this)!=DialogResult.OK){status.Text=T("Verified update saved: ","已校验的更新保存在：","已校驗的更新儲存在：")+workspace;Log(status.Text);return;}}
 try{SelfUpdate.Start(staged);Close();}catch(Exception e){UiDialogs.Error(this,e.Message,Text,T("Close","关闭","關閉"));}
