 void Run(Action action,Action success,Action failure=null){if(busy)return;diagnosticSnapshot=Details(false);busy=true;UpdateState();status.Text=T("Working…","正在处理…","正在處理…");var worker=new BackgroundWorker();worker.DoWork+=(s,e)=>action();worker.RunWorkerCompleted+=(s,e)=>{busy=false;UpdateState();if(e.Error!=null){if(failure!=null)failure();Log("ERROR: "+e.Error.Message);RefreshList(null);status.Text=T("Operation did not complete; see Diagnostics / logs.","操作未完成，可在“诊断 / 日志”中查看详情。","操作未完成，可在「診斷 / 日誌」中查看詳情。");UiDialogs.Error(this,e.Error.Message,Text,T("Close","关闭","關閉"));}else{status.Text=T("Ready.","就绪。","就緒。");if(success!=null)success();}worker.Dispose();};worker.RunWorkerAsync();}
 void Log(string text){if(InvokeRequired){Invoke((MethodInvoker)(()=>Log(text)));return;}string line=DateTime.Now.ToString("HH:mm:ss")+" "+text+Environment.NewLine;log.AppendText(line);if(diagnosticLog!=null&&!diagnosticLog.IsDisposed)diagnosticLog.AppendLog(line,followLog.Checked);}
 string Details(bool includeLog=true){var b=new StringBuilder();b.AppendLine(Text);b.AppendLine("OS: "+Environment.OSVersion+"; x64: "+Environment.Is64BitOperatingSystem);b.AppendLine("Steam: "+steam);foreach(var g in games){b.AppendLine(g.Name+" | "+g.AppId+" | "+g.Root+" | "+RowStatus(g));var p=Profile(g);if(p!=null)b.AppendLine("Launch mode: "+p.Mode+"; EXE: "+p.Exe);RepairContext ctx;if(contexts.TryGetValue(g.Root,out ctx)){b.AppendLine(Analyzer.Render(ctx.Report));if(ctx.Plan!=null)b.AppendLine(AutoBridge.Describe(ctx.Plan));b.AppendLine(ctx.Error);}}b.AppendLine("Zstd module target client SHA256: "+ZstdSupport.SupportedClientHash);if(includeLog)b.AppendLine(log.Text);return b.ToString();}
