 var d=new ThemedForm{Text=T("Diagnostics / logs","诊断 / 日志","診斷 / 日誌"),Size=new Size(900,620),MinimumSize=new Size(760,480),StartPosition=FormStartPosition.CenterParent,Font=Font,BackColor=UiTheme.Background,ForeColor=UiTheme.Text};diagnostics=d;
