 var tabs=new TabControl{Dock=DockStyle.Fill};var summaryTab=new TabPage(T("Diagnostics","诊断信息","診斷資訊"));var logTab=new TabPage(T("Live log","实时日志","即時日誌"));tabs.TabPages.Add(summaryTab);tabs.TabPages.Add(logTab);layout.Controls.Add(tabs,0,1);
 diagnosticSummary=new TextBox{Dock=DockStyle.Fill,Multiline=true,ReadOnly=true,ScrollBars=ScrollBars.Both,WordWrap=false,Text=busy?diagnosticSnapshot:Details(false)};summaryTab.Controls.Add(diagnosticSummary);
 diagnosticLog=new DiagnosticsLogBox{Dock=DockStyle.Fill,Multiline=true,ReadOnly=true,ScrollBars=ScrollBars.Both,WordWrap=false,Text=log.Text};logTab.Controls.Add(diagnosticLog);tabs.SelectedTab=logTab;
 Action<string,Action> add=(name,action)=>{var button=new StyledButton{Text=name,Width=155,Height=36,Margin=new Padding(0,0,8,0)};button.Click+=(sender,e)=>{try{action();}catch(Exception error){UiDialogs.Error(d,error.Message,Text,T("Close","关闭","關閉"));}};bar.Controls.Add(button);};
