static class Program {[STAThread]static void Main(string[] args){try{if(args.Length==3&&args[0]=="--enable-zstd"){Environment.ExitCode=ZstdSupport.Elevated(args[1],args[2]);return;}if(args.Length==2&&args[0]=="--apply-update"){Environment.ExitCode=SelfUpdate.Worker(args[1]);return;}Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);Application.Run(new MainForm());}catch(Exception e){MessageBox.Show(e.ToString(),"LegacySteamFixer startup error");}}}
